var i=`1155-butter-tarts`;var r=`world-1155`;var n=`CA`;var a=`northern-america`;var s=8;var o=61;var u={en:`Butter Tarts`,ua:`Масляні тарти`};var d={en:`Butter Tarts is a dish from Canada prepared with all-purpose flour, chicken egg, raisin. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Масляні тарти, страва кухні країни Канада, яку готують із таких продуктів: пшеничне борошно універсальне, куряче яйце, родзинки. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,380,`g`],[`unsalted-butter`,190,`g`],[`water`,115,`ml`],[`table-salt`,4,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`brown-sugar`,190,`g`],[`maple-syrup`,130,`ml`],[`chicken-egg`,2,`pcs`],[`unsalted-butter`,65,`g`],[`raisin`,110,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 24 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 24 хвилин до готовності.`,t:[`baking`],m:24,i:[]}];var g={slug:i,id:r,country:`CA`,region:a,servings:8,minutes:61,title:u,text:d,steps:l};export{n as country,g as default,r as id,o as minutes,a as region,s as servings,i as slug,l as steps,d as text,u as title};